SELECT 'core-2026-09-v4','small-quantities','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"small-quantities","title":"Few, a few, little and a little","level":"A2","order":15,"summary":"Distinguish a small useful amount from a shortage, with countable and uncountable nouns.","learningGoals":["A positive small amount","Emphasising a shortage","Read the meaning as well as the noun"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"A positive small amount","explanation":"A few goes with plural countable nouns. A little and a bit of go with uncountable nouns. These expressions can present the amount positively.","examples":["A few volunteers can help.","We have a little energy left."]},{"title":"Emphasising a shortage","explanation":"Few with plural nouns and little or very little with uncountable nouns emphasise scarcity. The surrounding context tells us whether the quantity feels sufficient.","examples":["Few volunteers signed up; we need more.","There is very little energy left."]},{"title":"Read the meaning as well as the noun","explanation":"A few and few have different emphasis despite both referring to small numbers. Do not treat all small quantities as shortages.","examples":["We have a few useful ideas.","We have few useful ideas, unfortunately."]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-small-quantities"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."},"chapter":{"introduction":["Small-quantity words combine two decisions: whether the noun is countable and whether the speaker presents the amount positively or as a shortage. The tiny article a can change the emphasis substantially. These words do not normally give an exact number."],"rules":[{"title":"A positive small amount","explanation":"A few goes with plural countable nouns. A little and a bit of go with uncountable nouns. These expressions can present the amount positively.","examples":["A few volunteers can help.","We have a little energy left.","We have **a few** seats, so you can join us."],"pattern":"**a few** books / **few** books","paragraphs":["A few goes with plural count nouns and presents some as available. Few without a often stresses that the number is disappointingly small. The same facts can receive a different emphasis: a few friends sounds more positive than few friends."],"id":"small-quantities-foundation-1","domain":"noun-phrases","referenceIds":["bc-small-quantities"],"readingVersion":"foundations-2026-09-v2"},{"title":"Emphasising a shortage","explanation":"Few with plural nouns and little or very little with uncountable nouns emphasise scarcity. The surrounding context tells us whether the quantity feels sufficient.","examples":["Few volunteers signed up; we need more.","There is very little energy left.","We have **few** seats left, so book soon."],"pattern":"**a little** time / **very little** time","paragraphs":["A little goes with uncountable nouns and presents a small amount positively. Little or very little stresses scarcity. Do not use a few with ordinary uncountable advice or equipment. A unit phrase can make a countable expression: a few pieces of advice."],"id":"small-quantities-foundation-2","domain":"noun-phrases","referenceIds":["bc-small-quantities"],"readingVersion":"foundations-2026-09-v2"},{"title":"Read the meaning as well as the noun","explanation":"A few and few have different emphasis despite both referring to small numbers. Do not treat all small quantities as shortages.","examples":["We have a few useful ideas.","We have few useful ideas, unfortunately.","There is **a little** time, but **very little** space."],"pattern":"**a bit of** help","paragraphs":["A bit of is an informal small-amount phrase before an uncountable noun. A little can also modify an adjective or adverb in other structures. Identify the following word’s role before applying a noun-quantity rule."],"id":"small-quantities-foundation-3","domain":"noun-phrases","referenceIds":["bc-small-quantities"],"readingVersion":"foundations-2026-09-v2"},{"title":"Contrasts and edge cases","explanation":"Only a few or only a little can make a small amount sound limiting even though a remains. Few/little are not exact synonyms of none: they typically mean a small quantity, possibly close to zero. In informal speech, not many or not much may be more natural than few or little in some contexts.","examples":["We have **a few** seats, so you can join us.","We have **few** seats left, so book soon.","There is **a little** time, but **very little** space."],"id":"small-quantities-foundation-4","domain":"noun-phrases","referenceIds":["bc-small-quantities"],"readingVersion":"foundations-2026-09-v2"}],"recap":["**a few** books / **few** books","**a little** time / **very little** time","**a bit of** help"],"readingVersion":"core-2026-09-v4"},"stage":"2 · Everyday descriptions","prerequisites":["countable-uncountable"],"readingReferenceIds":["bc-small-quantities"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='small-quantities'
